import torch.nn as nn
from torch.utils.cpp_extension import load_inline

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

        cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 16
#define BLOCK_ROWS 4

__global__ void matmul_kernel_reg_blocking(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col = bx * TILE_DIM + tx;

    float C_values[BLOCK_ROWS][BLOCK_ROWS] = {{0.0f}};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        if (row < N && (t * TILE_DIM + tx) < N) {
            As[ty][tx] = A[row * N + t * TILE_DIM + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((t * TILE_DIM + ty) < N && col < N) {
            Bs[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }
        __syncthreads();

        // Multiply tiles
        for (int k = 0; k < TILE_DIM; ++k) {
            for(int i = 0; i < BLOCK_ROWS; ++i) {
                for(int j = 0; j < BLOCK_ROWS; ++j) {
                    C_values[i][j] += As[ty + i][k] * Bs[k][tx + j];
                }
            }
        }
        __syncthreads();
    }

    for(int i = 0; i < BLOCK_ROWS; ++i) {
        for(int j = 0; j < BLOCK_ROWS; ++j) {
            if ((row + i) < N && (col + j) < N) {
                C[(row + i) * N + (col + j)] = C_values[i][j];
            }
        }
    }
}

